mapper.select:
SELECT r.reg_id AS user_id FROM t_recruit r
 WHERE r.recruit_id = #{recruitId}::integer AND r.use_yn = 'Y' AND r.reg_id <> #{userId}
UNION
SELECT a.user_id FROM t_recruit_apply a
 WHERE a.recruit_id = #{recruitId}::integer AND a.use_yn = 'Y'
   AND a.apply_status = 'APPLY02' AND a.user_id <> #{userId}
